package android.content;import java.util.*;public class Intent {public static final String ACTION_BOOT_COMPLETED="boot",ACTION_MY_PACKAGE_REPLACED="replace";public final Class<?> type;private String action;private final Map<String,Object> data=new HashMap<>();public Intent(Context c,Class<?> t){type=t;}public Intent setAction(String s){action=s;return this;}public String getAction(){return action;}public Intent putExtra(String k,String v){data.put(k,v);return this;}public String getStringExtra(String k){return (String)data.get(k);}}
